INSERT INTO public.gatos OVERRIDING SYSTEM VALUE VALUES (24, 'Freya', 'Adulto', 'Fêmea', 'Uma gatinha tímida que espera por uma família disposta a conquistá-la com carinho.', 'Tímida e reservada, precisa de uma adoção paciente para aprender a confiar e se sentir segura.', 'data:image/jpeg;base64,', true, false, true, '2026-09-25 17:53:53.409187', 'Negativo', 'Negativo');
INSERT INTO public.gatos OVERRIDING SYSTEM VALUE VALUES (26, 'Pudim', 'Filhote', 'Fêmea', 'Um doce de gatinha que adora estar pertinho e acompanhar cada passo seu.', 'Curiosa e brincalhona, segue você por todo canto e está sempre pronta para uma nova aventura.', 'data:image/jpeg;base64,', false, false, true, '2026-09-25 18:00:11.931397', 'Positivo', 'Negativo');
INSERT INTO public.gatos OVERRIDING SYSTEM VALUE VALUES (27, 'Adelaide', 'Adulto', 'Fêmea', 'Uma gatinha cheia de carinho, que só quer ter alguém para chamar de seu.', 'Extremamente carinhosa e companheira, adora estar pertinho e fazer companhia.', 'data:image/jpeg;base64,', false, false, true, '2026-09-25 21:58:27.367816', 'Positivo', 'Negativo');
INSERT INTO public.gatos OVERRIDING SYSTEM VALUE VALUES (29, 'Jordana', 'Adulto', 'Fêmea', 'Uma gatinha delicada que, aos poucos, está descobrindo como é bom receber carinho.', 'Assustada no início, mas aceita carinho e está aprendendo a confiar.', 'data:image/jpeg;base64,', true, true, true, '2026-09-25 22:04:22.599007', 'Negativo', 'Negativo');
INSERT INTO public.gatos OVERRIDING SYSTEM VALUE VALUES (30, 'Thamires', 'Adulto', 'Fêmea', 'Chegou ainda filhote e cresceu esperando por uma família para chamar de sua.', 'Tímida no início, mas aceita carinho. É brincalhona e tem muito amor para descobrir.', 'data:image/jpeg;base64,', true, true, true, '2026-09-25 22:07:26.276223', 'Negativo', 'Negativo');
INSERT INTO public.gatos OVERRIDING SYSTEM VALUE VALUES (21, 'Neném', 'Adulto', 'Fêmea', 'Uma gatinha tímida que só precisa de tempo para descobrir o amor de um lar.', 'Muito medrosa no início, precisa de paciência e carinho para aprender a confiar.', 'data:image/jpeg;base64,', true, false, true, '2026-09-25 14:39:43.414984', 'Negativo', 'Negativo');
INSERT INTO public.gatos OVERRIDING SYSTEM VALUE VALUES (25, 'Nayara', 'Adulto', 'Fêmea', 'Carinhosa e dengosa, Nayara viu todos seus filhotes encontrarem um lar e continua esperando pelo seu.', 'Muito amorosa, adora carinho e sonha em também ter uma família para chamar de sua.', 'data:image/jpeg;base64,', true, false, true, '2026-09-25 17:55:17.130415', 'Negativo', 'Negativo');
INSERT INTO public.gatos OVERRIDING SYSTEM VALUE VALUES (20, 'Pitanga', 'Adulto', 'Fêmea', 'Essa jovem gatinha de 1 ano é muito dócil, carinhosa e ama uma brincadeira.', 'Além de brincalhona, é muito sociável e adora a companhia de outros gatinhos.', 'data:image/jpeg;base64,', true, true, true, '2026-09-25 14:36:41.519492', 'Negativo', 'Negativo');
INSERT INTO public.gatos OVERRIDING SYSTEM VALUE VALUES (28, 'Ellie', 'Adulto', 'Fêmea', 'Uma gatinha carinhosa e falante que sonha em ter todo o amor só para ela.', 'Carente e muito apegada às pessoas, prefere ser filha única e não se dá muito bem com outros gatinhos.', 'data:image/jpeg;base64,', true, true, true, '2026-09-25 22:02:16.014483', 'Negativo', 'Negativo');
INSERT INTO public.gatos OVERRIDING SYSTEM VALUE VALUES (19, 'Crystal', 'Adulto', 'Fêmea', 'Encontrada no estacionamento de um condomínio, ela só quer encontrar alguém para amar.', 'Muito carinhosa e apaixonada por colo, espera por uma chance de mostrar todo o amor que tem para dar.', 'data:image/jpeg;base64,', false, false, true, '2026-09-25 14:33:39.091219', 'Negativo', 'Positivo');
INSERT INTO public.gatos OVERRIDING SYSTEM VALUE VALUES (22, 'Nestor', 'Idoso', 'Macho', 'Um gatão enorme, cheio de amor e pronto para conquistar um coração.', 'Extremamente carinhoso, adora receber carinho e estar pertinho das pessoas.', 'data:image/jpeg;base64,', true, false, true, '2026-09-25 14:43:03.304085', 'Positivo', 'Negativo');
INSERT INTO public.gatos OVERRIDING SYSTEM VALUE VALUES (18, 'Morgana', 'Adulto', 'Fêmea', 'Uma gatinha delicada que, aos poucos, está descobrindo como é gostoso receber carinho.', 'Tímida no início, mas se derrete quando confia. É muito apegada ao Carvão e adora ter seu companheiro por perto.', 'data:image/jpeg;base64,', true, false, true, '2026-09-25 02:08:44.104117', 'Negativo', 'Negativo');
INSERT INTO public.gatos OVERRIDING SYSTEM VALUE VALUES (23, 'Carvão', 'Adulto', 'Macho', 'Um gatinho carinhoso que adora receber atenção e estar pertinho de quem ama.', 'Ama um carinho e está sempre ao lado da Morgana, sua companheira inseparável.', 'data:image/jpeg;base64,', true, false, true, '2026-09-25 14:47:29.082299', 'Negativo', 'Negativo');


